def transform(grid):
    """Fill a zero-valued top row with the color of the bottom row."""
    out = [row[:] for row in grid]
    if out and out[0] and all(value == 0 for value in out[0]):
        color = out[-1][0]
        out[0] = [color] * len(out[0])
